    # Başlangıç teması (varsayılan `rewloy`, panelle aynı); gönderilen alanlar bunun üstüne yazılır
    preset: Literal["rewloy", "kahve", "firin", "berber", "guzellik", "pizza", "burger", "spor", "pati", "cicek", "tatli", "kitap", "yikama", "market", "gece", "sade"]
    # Programın adı (boşsa türün adı)
    programName: str
    # Apple düzeni; türe göre izinli olanlar: `GET /v1/programs/design-options`
    appleStyle: Literal["storeCard", "coupon", "generic"]
    # #rrggbb
    backgroundColor: str
    # #rrggbb
    foregroundColor: str
    # #rrggbb
    labelColor: str
    # #rrggbb
    stampAccentColor: str
    # Kart sayfasında son 90 günün sıralaması (hediye kartı, kupon ve indirimde yok)
    leaderboard: bool
    # Kasanın bu programın kartlarında işlem yapabileceği şubeler; boş = hepsi. Başka şubede `WRONG_LOCATION` döner; online siparişler etkilenmez.
    validLocationIds: List[str]
    # 1.3.0: yeni kartın alınabildiği günler (işletmenin saat diliminde, `until` dahil). Dışında hiçbir kapı yeni kart vermez (şube QR'ları, kartın bağlantısı, Rewloy Cüzdan, kart sahibi ve kimliksiz katılım: `410 JOIN_CLOSED`); personelin kart açması (`POST /v1/passes`) etkilenmez, alınmış kartlar çalışır. Genelde bir şube QR'ının zamanlamasından yazılır; `null` kaldırır.
    joinWindow: Optional[PreviewProgramBodyConfigJoinWindow]
    # Katılım formunda e-postadan başka sorulanlar
    signupFields: List[PreviewProgramBodyConfigSignupFieldsItem]
    # Google yorum bağlantısı (g.page, maps.app.goo.gl, google.com/maps…); boş dize kaldırır
    reviewUrl: str
    # Her platformdaki görünüm. Verilmeyen alanlar mevcut tasarımdan (ya da renklerden türetilen varsayılandan) kalır.
    design: PreviewProgramBodyConfigDesign
    # Damga: ödül için gereken damga
    maxStamps: int
    stampIcon: Literal["coffee", "star", "heart", "check", "gift", "cart", "scissors", "bread", "pizza", "burger", "cupcake", "icecream", "dumbbell", "paw", "flower", "book", "drop", "leaf", "crown", "shirt"]
    rewardName: str
    # Damga: ödül hazırken damga birikmeye devam eder
    allowOverflow: bool
    # Puan: her 1 birim harcamaya puan; satışta aşağı yuvarlanır, `floor(amountMinor / 100 × earnRate)`
    earnRate: int
    pointsRewards: List[PreviewProgramBodyConfigPointsRewardsItem]
    discountPercent: int
    discountTerms: str
    # VIP seviyeleri; ilk seviye her zaman 0 ziyaretle başlar
    tiers: List[PreviewProgramBodyConfigTiersItem]
    # Cashback yüzdesi (tam sayı); satışta aşağı yuvarlanır, `floor(amountMinor × cashbackRate / 100)` kuruş
    cashbackRate: int
    # Kupon: teklif metni
    offerText: str
    # Kupon: online mağazada kullanıldığında değeri. Yoksa (ya da null) kupon yalnız mağazada geçer; kodun kendi online değeri ya da tutarı bunun önüne geçer.
    onlineValue: Optional[PreviewProgramBodyConfigOnlineValue]
    # 1.3.0: hediye kartının değeri (kuruş). Kartın şartıdır: her kod bununla kart verir (kod kendi `valueMinor`'ını göndermedikçe). Panelde yeni hediye kartında zorunludur; 1.3.0 öncesi kartlarda yoktur.
    giftValueMinor: Optional[int]
    # 1.3.0: kupon: bir ürün (`offerText`) yerine bir tutar indirimi (kuruş); `offerText` varsa o geçer
    offerValueMinor: Optional[int]
    # 1.3.0: kupon ve indirim kartı: bir kart kaç kez kullanılır. Yalnız koddan alınan kartlara uygulanır; kodsuz verilen kart (`POST /v1/passes`) türün varsayılanındadır (kupon tek, indirim sınırsız)
    usage: Literal["once", "limited", "unlimited"]
    # 1.3.0: `usage: limited` ile kullanım sayısı
    usageLimit: int
    # 1.3.0: alınan kartın geçerliliği: `none` süresiz, `until` bir güne kadar (dahil, işletmenin saat diliminde), `days` alındıktan N gün. Her kart aldığı günün kuralını saklar; değişiklik yalnız sonra alınan kartlara uygulanır (var olanlar `POST /v1/programs/{id}/extend` ile uzatılır)
    validity: Optional[PreviewProgramBodyConfigValidity]
    # 1.3.0: kartın koşulları, işletmenin sözleriyle: alırken, devam ekranında ve kartın arkasında görünür
    terms: Optional[str]


